import type { Plugin } from "rollup";
import { normalize } from "./config.js";
import { boot } from "./server.js";

export { normalize, defaults, serverDefaults } from "./config.js";
export type { DevServerConfig, ProxyItem, ServerConfig } from "./config.js";
export { init } from "./init.js";

export default function devServer(
  opts: Parameters<typeof normalize>[0] = {},
): Plugin {
  let booted = false;
  let server: any;
  return {
    name: "dev-server",
    async closeWatcher() {
      booted = false;
      if (server) await server.close();
    },
    async writeBundle() {
      if (booted) return;
      booted = true;
      try {
        const config = normalize(opts);
        if (!this.meta.watchMode) {
          if (!config.force) return;
          else
            this.warn(
              `Starting dev-server even though we're not in watch mode`,
            );
        }
        server = await boot(config);
      } catch (err) {
        this.error(err as Error);
      }
    },
  };
}
